import{_ as n,c as e,o,ae as i}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Buttons (CSV / Print)","description":"Buttons (CSV / Print)","frontmatter":{"title":"Buttons (CSV / Print)","description":"Buttons (CSV / Print)"},"headers":[],"relativePath":"guide/table-settings/csv-and-print-button.md","filePath":"guide/table-settings/csv-and-print-button.md"}'),r={name:"guide/table-settings/csv-and-print-button.md"};function a(s,t,l,u,h,b){return o(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="buttons-csv-print" tabindex="-1">Buttons (CSV / Print) <a class="header-anchor" href="#buttons-csv-print" aria-label="Permalink to &quot;Buttons (CSV / Print)&quot;">​</a></h1><p>Ninja Tables offers you an amazing feature that is CSV Export / Print Button Settings for Frontend. You can enable/disable Print and CSV export settings according to your needs. Buttons (CSV / Print) is a Pro Feature!</p><h2 id="csv-print-button-in-ninja-tables" tabindex="-1">CSV/Print Button in Ninja Tables <a class="header-anchor" href="#csv-print-button-in-ninja-tables" aria-label="Permalink to &quot;CSV/Print Button in Ninja Tables&quot;">​</a></h2><ul><li>Clicking the <strong>Table</strong> <strong>Configuration</strong> tab, you will find a new window appearing with the **Buttons (CSV / Print) **option on the sidebar.</li><li>Click on the <strong><strong>Buttons (CSV / Print)</strong></strong>, there a new tab will open with a <strong>CSV Export / Print Button Settings</strong> <strong>for Frontend</strong> area. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-buttoncsv-1024x595.webp" alt="New Ui button-csv"> Now, let&#39;s talk about the details of the Settings area.</li></ul><h3 id="csv-export-print-button-settings-for-frontend" tabindex="-1"><strong>CSV Export / Print Button Settings</strong> for Frontend <a class="header-anchor" href="#csv-export-print-button-settings-for-frontend" aria-label="Permalink to &quot;**CSV Export / Print Button Settings** for Frontend&quot;">​</a></h3><ul><li>To display the CSV Export button or print on the preview table, enable them. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-csvprint-button-settings-1024x897.webp" alt="New Ui csv:print button settings"></li><li>Some more options will show up after these button has been enabled.</li><li>**Button Label: **It displays the text you want to appear on the button label, where you can add any text that meets your needs.</li><li>**Button Background Color: **It reveals the button&#39;s background color.</li><li>**Button Text Color: **It displays the button&#39;s text color.</li><li><strong>Export as Plain Text:</strong> Your button will export as plain text if you enable this.</li></ul><h3 id="print-button-settings" tabindex="-1"><strong>Print Button Settings</strong> <a class="header-anchor" href="#print-button-settings" aria-label="Permalink to &quot;**Print Button Settings**&quot;">​</a></h3><ul><li>To display the Print button on the preview table, enable the Print Button Settings.</li><li>Some options will show up after the Print button has been selected.</li><li>**Button Label: **It displays the text you want to appear on the button label, where you can add any text that meets your needs.</li><li>**Button Background Color: **It reveals the button&#39;s background color.</li><li>**Button Text Color: **It displays the button&#39;s text color.</li><li><strong>Print Screen Header:</strong> If you choose <strong>Yes</strong> to include a <strong>header on each page</strong> in the <strong>Print Screen Header</strong> option and enter the header text in the HTML content box below, the header text of each page will be displayed once you press the Print button.</li><li><strong>Print Screen Footer:</strong> In the Print Screen Footer option, if you select **Yes **to the <strong>Footer on</strong> each page and enter the text for the footer in the HTML content section below, each page&#39;s footer will be displayed once you press the Print button.</li></ul><h3 id="buttons-position" tabindex="-1"><strong>Buttons Position</strong> <a class="header-anchor" href="#buttons-position" aria-label="Permalink to &quot;**Buttons Position**&quot;">​</a></h3><p>You can adjust the position of your button to suit your requirements. Your button can be placed in one of three places: After the search box, Before the table, or at the Bottom of the table.</p><h3 id="buttons-alignment" tabindex="-1"><strong>Buttons Alignment</strong> <a class="header-anchor" href="#buttons-alignment" aria-label="Permalink to &quot;**Buttons Alignment**&quot;">​</a></h3><p>Your buttons&#39; alignment can be changed as needed. The button alignment has three options: Left, Center, and Right. When you are done with the configuration, don&#39;t forget to click on the <strong>Update</strong> <strong>Settings</strong> button. Let&#39;s see the Preview Table after you complete the settings. <img src="https://ninjatables.com/wp-content/uploads/2023/01/buttons-csv-print-6-1024x397.png" alt="table with print button"> A CSV file will be downloaded when you click on the CSV button and several printing options will appear if you click the Print button. This is how you can quickly use and style your CSV and Print buttons to match your needs.</p>',12)])])}const p=n(r,[["render",a]]);export{d as __pageData,p as default};
